PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,role TEXT NOT NULL,password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schools(id TEXT PRIMARY KEY,name TEXT NOT NULL,legal_name TEXT NOT NULL,cnpj TEXT UNIQUE NOT NULL,address TEXT NOT NULL DEFAULT '',contact TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS representatives(id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES schools(id),name TEXT NOT NULL,email TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contracts(id TEXT PRIMARY KEY,school_id TEXT NOT NULL REFERENCES schools(id),parent_id TEXT REFERENCES contracts(id),sequence INTEGER,start TEXT,end TEXT,status TEXT NOT NULL DEFAULT 'Em preparação',UNIQUE(parent_id,sequence));
CREATE TABLE IF NOT EXISTS templates(id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS template_versions(id TEXT PRIMARY KEY,template_id TEXT NOT NULL REFERENCES templates(id),version INTEGER NOT NULL,status TEXT NOT NULL,body TEXT NOT NULL,bytes BLOB,approved_by TEXT REFERENCES users(id),UNIQUE(template_id,version));
CREATE TRIGGER IF NOT EXISTS immutable_template BEFORE UPDATE ON template_versions WHEN OLD.status='aprovado' BEGIN SELECT RAISE(ABORT,'Versão aprovada é imutável'); END;
CREATE TABLE IF NOT EXISTS demands(id TEXT PRIMARY KEY,glpi_id TEXT UNIQUE,school_id TEXT NOT NULL REFERENCES schools(id),contract_id TEXT REFERENCES contracts(id),type TEXT NOT NULL,stage TEXT NOT NULL,priority TEXT NOT NULL,owner TEXT NOT NULL REFERENCES users(id),due TEXT NOT NULL,data TEXT NOT NULL,data_version INTEGER NOT NULL DEFAULT 1,confirmed INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL,completed TEXT);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,demand_id TEXT NOT NULL REFERENCES demands(id),version INTEGER NOT NULL,template_version TEXT NOT NULL REFERENCES template_versions(id),data_version INTEGER NOT NULL,snapshot TEXT NOT NULL,bytes BLOB NOT NULL,signed BLOB,author TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL,UNIQUE(demand_id,version));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),status TEXT NOT NULL,results TEXT NOT NULL,author TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),data_version INTEGER NOT NULL,kind TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL,valid INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,demand_id TEXT REFERENCES demands(id),user_id TEXT REFERENCES users(id),action TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_logs(id TEXT PRIMARY KEY,status TEXT NOT NULL,imported INTEGER NOT NULL,message TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
